package com.quickmanager.controller;

import com.quickmanager.service.InvoiceService;
import com.quickmanager.service.ProductService;
import javafx.fxml.FXML;
import javafx.scene.control.Label;

import java.time.LocalDate;

public class HomeController {
	@FXML private Label lblDoanhThuHomNay;
	@FXML private Label lblDonHangHomNay;
	@FXML private Label lblSPBanRa;
	@FXML private Label lblSPSapHet;

	public void initialize() {
		loadHomeSummary();
	}

	private void loadHomeSummary() {
		LocalDate today = LocalDate.now();
		java.math.BigDecimal doanhThu = InvoiceService.getTotalRevenue(today, today);
		int soHoaDon = InvoiceService.getOrderCount(today, today);
		int soSpBan = InvoiceService.getProductsSold(today, today);
		java.util.List<com.quickmanager.model.CanhBaoTonKho> low = ProductService.getLowStock(10);

		lblDoanhThuHomNay.setText(String.format("%,d VNĐ", doanhThu.longValue()));
		lblDonHangHomNay.setText(String.valueOf(soHoaDon));
		lblSPBanRa.setText(String.valueOf(soSpBan));
		lblSPSapHet.setText(String.valueOf(low.size()));
	}
}

package com.quickmanager.controller;

import com.quickmanager.model.CanhBaoTonKho;
import com.quickmanager.model.DoanhThuNgay;
import com.quickmanager.model.TopSanPham;
import com.quickmanager.service.InvoiceService;
import com.quickmanager.service.ProductService;
import javafx.collections.FXCollections;
import javafx.fxml.FXML;
import javafx.scene.control.*;
import javafx.scene.control.cell.PropertyValueFactory;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class StatisticsController {
	@FXML private DatePicker dpTuNgay;
	@FXML private DatePicker dpDenNgay;
	@FXML private ComboBox<String> cbKieuThongKe;
	@FXML private Button btnThongKe;

	@FXML private Label lblDoanhThu;
	@FXML private Label lblSoHoaDon;
	@FXML private Label lblSanPhamBan;

	@FXML private TableView<DoanhThuNgay> tblDoanhThuNgay;
	@FXML private TableColumn<DoanhThuNgay, String> colNgay;
	@FXML private TableColumn<DoanhThuNgay, Integer> colSoHoaDonNgay;
	@FXML private TableColumn<DoanhThuNgay, String> colDoanhThuNgay;

	@FXML private TableView<TopSanPham> tblTopSanPham;
	@FXML private TableColumn<TopSanPham, String> colTopTenSP;
	@FXML private TableColumn<TopSanPham, Integer> colTopSoLuong;
	@FXML private TableColumn<TopSanPham, String> colTopDoanhThu;

	@FXML private TableView<CanhBaoTonKho> tblTonKhoThap;
	@FXML private TableColumn<CanhBaoTonKho, Integer> colCanhBaoMaSP;
	@FXML private TableColumn<CanhBaoTonKho, String> colCanhBaoTenSP;
	@FXML private TableColumn<CanhBaoTonKho, Integer> colCanhBaoTonKho;
	@FXML private TableColumn<CanhBaoTonKho, Integer> colCanhBaoMucToiThieu;
	@FXML private TableColumn<CanhBaoTonKho, String> colCanhBaoTrangThai;

	private final DateTimeFormatter df = DateTimeFormatter.ofPattern("yyyy-MM-dd");

	@FXML
	public void initialize() {
		// set default dates
		if (dpDenNgay != null) dpDenNgay.setValue(LocalDate.now());
		if (dpTuNgay != null) dpTuNgay.setValue(LocalDate.now().minusDays(7));

		if (cbKieuThongKe != null) {
			cbKieuThongKe.getItems().setAll("Doanh thu", "Số hóa đơn", "Sản phẩm bán ra");
			cbKieuThongKe.getSelectionModel().selectFirst();
		}

		initTables();
		if (btnThongKe != null) btnThongKe.setOnAction(e -> doThongKe());
		doThongKe();
	}

	private void initTables() {
		if (colNgay != null) colNgay.setCellValueFactory(cd -> new javafx.beans.property.SimpleStringProperty(cd.getValue().getNgay().format(df)));
		if (colSoHoaDonNgay != null) colSoHoaDonNgay.setCellValueFactory(new PropertyValueFactory<>("soHoaDon"));
		if (colDoanhThuNgay != null) colDoanhThuNgay.setCellValueFactory(cd -> new javafx.beans.property.SimpleStringProperty(String.format("%,d", cd.getValue().getDoanhThu().longValue())));

		if (colTopTenSP != null) colTopTenSP.setCellValueFactory(new PropertyValueFactory<>("tenSanPham"));
		if (colTopSoLuong != null) colTopSoLuong.setCellValueFactory(new PropertyValueFactory<>("soLuong"));
		if (colTopDoanhThu != null) colTopDoanhThu.setCellValueFactory(cd -> new javafx.beans.property.SimpleStringProperty(String.format("%,d", cd.getValue().getDoanhThu().longValue())));

		if (colCanhBaoMaSP != null) colCanhBaoMaSP.setCellValueFactory(new PropertyValueFactory<>("maSanPham"));
		if (colCanhBaoTenSP != null) colCanhBaoTenSP.setCellValueFactory(new PropertyValueFactory<>("tenSanPham"));
		if (colCanhBaoTonKho != null) colCanhBaoTonKho.setCellValueFactory(new PropertyValueFactory<>("tonKho"));
		if (colCanhBaoMucToiThieu != null) colCanhBaoMucToiThieu.setCellValueFactory(new PropertyValueFactory<>("mucToiThieu"));
		if (colCanhBaoTrangThai != null) colCanhBaoTrangThai.setCellValueFactory(new PropertyValueFactory<>("trangThai"));
	}

	private void doThongKe() {
		LocalDate from = (dpTuNgay == null) ? LocalDate.of(2020,1,1) : dpTuNgay.getValue();
		LocalDate to = (dpDenNgay == null) ? LocalDate.now() : dpDenNgay.getValue();
		if (from == null) from = LocalDate.of(2020,1,1);
		if (to == null) to = LocalDate.now();

		java.math.BigDecimal total = InvoiceService.getTotalRevenue(from, to);
		int hoaDon = InvoiceService.getOrderCount(from, to);
		int spBan = InvoiceService.getProductsSold(from, to);

		if (lblDoanhThu != null) lblDoanhThu.setText(String.format("%,d VNĐ", total.longValue()));
		if (lblSoHoaDon != null) lblSoHoaDon.setText(String.valueOf(hoaDon));
		if (lblSanPhamBan != null) lblSanPhamBan.setText(String.valueOf(spBan));

		if (tblDoanhThuNgay != null) tblDoanhThuNgay.setItems(FXCollections.observableArrayList(InvoiceService.getDoanhThuTheoNgay(from, to)));
		if (tblTopSanPham != null) tblTopSanPham.setItems(FXCollections.observableArrayList(InvoiceService.getTopSanPham(from, to, 10)));
		if (tblTonKhoThap != null) tblTonKhoThap.setItems(FXCollections.observableArrayList(ProductService.getLowStock(10)));
	}
}

package com.quickmanager.model;

public class CanhBaoTonKho {
    private int maSanPham;
    private String tenSanPham;
    private int tonKho;
    private int mucToiThieu;
    private String trangThai;

    public CanhBaoTonKho(int maSanPham, String tenSanPham, int tonKho, int mucToiThieu, String trangThai) {
        this.maSanPham = maSanPham;
        this.tenSanPham = tenSanPham;
        this.tonKho = tonKho;
        this.mucToiThieu = mucToiThieu;
        this.trangThai = trangThai;
    }

    public int getMaSanPham() { return maSanPham; }
    public String getTenSanPham() { return tenSanPham; }
    public int getTonKho() { return tonKho; }
    public int getMucToiThieu() { return mucToiThieu; }
    public String getTrangThai() { return trangThai; }
}

package com.quickmanager.model;

import java.math.BigDecimal;
import java.time.LocalDate;

public class DoanhThuNgay {
    private LocalDate ngay;
    private int soHoaDon;
    private BigDecimal doanhThu;

    public DoanhThuNgay(LocalDate ngay, int soHoaDon, BigDecimal doanhThu) {
        this.ngay = ngay;
        this.soHoaDon = soHoaDon;
        this.doanhThu = doanhThu;
    }

    public LocalDate getNgay() { return ngay; }
    public int getSoHoaDon() { return soHoaDon; }
    public BigDecimal getDoanhThu() { return doanhThu; }
}

package com.quickmanager.model;

import java.math.BigDecimal;

public class TopSanPham {
	private String tenSanPham;
	private int soLuong;
	private BigDecimal doanhThu;

	public TopSanPham(String tenSanPham, int soLuong, BigDecimal doanhThu) {
		this.tenSanPham = tenSanPham;
		this.soLuong = soLuong;
		this.doanhThu = doanhThu;
	}

	public String getTenSanPham() { return tenSanPham; }
	public int getSoLuong() { return soLuong; }
	public BigDecimal getDoanhThu() { return doanhThu; }
}

package com.quickmanager.service;

import com.quickmanager.config.DBConnection;
import com.quickmanager.debug.Address;
import com.quickmanager.model.CT_HoaDon;
import com.quickmanager.model.HoaDon;
import com.quickmanager.model.KhachHang;

import java.sql.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class InvoiceService {
    public static final String sqlInsertHD = """
    Insert Into HOA_DON ( MaNhanVien,MaKhachHang,TongTien,GiamGia,TienKhachDua,TienThoi)
    Values(?,?,?,?,?,?);
    """;
    private static final String sqlInsertCTHD =
            "INSERT INTO CT_HOA_DON (MaHoaDon, MaSanPham, SoLuong, DonGia, ThanhTien) VALUES (?, ?, ?, ?, ?)";

    private static final String sqlUpdateSP = """
    UPDATE SAN_PHAM
    SET SoLuongTon = SoLuongTon - ?,
        TrangThai = CASE
            WHEN SoLuongTon - ? <= 0 THEN N'Ngung ban'
            ELSE TrangThai
        END
    WHERE MaSanPham = ? AND SoLuongTon >= ?;
    """;


    public static int taoHoaDonNKH(HoaDon hd, List<CT_HoaDon> ds) throws SQLException {
        try (Connection con = DBConnection.getConnection()) {
            con.setAutoCommit(false);
            try (PreparedStatement psHD = con.prepareStatement(sqlInsertHD, Statement.RETURN_GENERATED_KEYS);
                PreparedStatement psCTHD = con.prepareStatement(sqlInsertCTHD);
                PreparedStatement psUDSP =  con.prepareStatement(sqlUpdateSP)) {

                // HD
                psHD.setInt(1, hd.getMaNhanVien());
                if (hd.getMaKhachHang() == null) psHD.setNull(2, Types.INTEGER);
                else psHD.setInt(2, hd.getMaKhachHang());
                psHD.setBigDecimal(3, hd.getTongTien());
                psHD.setBigDecimal(4, hd.getGiamGia());
                psHD.setBigDecimal(5, hd.getTienKhachDua());
                psHD.setBigDecimal(6, hd.getTienThoi());

                int ktHD = psHD.executeUpdate();
                if (ktHD == 0) throw new SQLException("Tạo hóa đơn thất bại");

                // CTHD
                int maHoaDon;
                try (ResultSet key = psHD.getGeneratedKeys()) {
                    if (key.next()) maHoaDon = key.getInt(1);
                    else throw new SQLException("Lấy mã hóa đơn thất bại");
                }

                for (CT_HoaDon items : ds) {
                    psUDSP.setInt(1, items.getSoLuong());
                    psUDSP.setInt(2, items.getSoLuong());
                    psUDSP.setInt(3, items.getMaSanPham());
                    psUDSP.setInt(4, items.getSoLuong());
                    int ktUDSP = psUDSP.executeUpdate();
                    if (ktUDSP != 1) throw new SQLException("Cập nhật sản phẩm thất bại");

                    psCTHD.setInt(1, maHoaDon);
                    psCTHD.setInt(2, items.getMaSanPham());
                    psCTHD.setInt(3, items.getSoLuong());
                    psCTHD.setBigDecimal(4, items.getDonGia());
                    psCTHD.setBigDecimal(5, items.getThanhTien());
                    psCTHD.executeUpdate();
                }
                con.commit();
                return maHoaDon;
            }catch (Exception e) {
                con.rollback();
                throw e;  // gui loi ra ngoai
            }

        }
    }

    public static final String sqlGetHoaDon = """
        Select *
        From HOA_DON as hd
        Left Join KHACH_HANG as kh on kh.MaKhachHang = hd.MaKhachHang
        Where hd.NgayLap >= ? and hd.NgayLap < ?
        And (kh.TenKhachHang Like ? or kh.TenKhachHang is null)
        And CAST(hd.MaHoaDon AS VARCHAR(20)) Like ?
        """;

    public static List<HoaDon> getHoaDon(String nameKH, String maHD, LocalDate start, LocalDate end) {
        List<HoaDon> ds = new ArrayList<>();
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020, 1, 1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        String nameFilter = (nameKH == null || nameKH.isBlank()) ? "%" : "%" + nameKH.trim() + "%";
        String maHdFilter = (maHD == null || maHD.isBlank()) ? "%" : "%" + maHD.trim() + "%";
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sqlGetHoaDon)) {
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            ps.setString(3, nameFilter);
            ps.setString(4, maHdFilter);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    ds.add(new HoaDon(
                            rs.getInt("MaHoaDon"),
                            rs.getInt("MaKhachHang"),
                            rs.getString("TenKhachHang"),
                            rs.getDate("NgayLap").toLocalDate(),
                            rs.getBigDecimal("TongTien"),
                            rs.getBigDecimal("GiamGia")));
                }
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    public static final String sqlGetCTHD = """
        SELECT 
            ROW_NUMBER() OVER (ORDER BY sp.MaSanPham) AS STT,
            hd.*,
            sp.*
        FROM CT_HOA_DON AS hd
        JOIN SAN_PHAM AS sp 
            ON hd.MaSanPham = sp.MaSanPham
        WHERE hd.MaHoaDon = ?
        """;
    public static List<CT_HoaDon> getCTHD(int maHD) {
        List<CT_HoaDon> ds = new ArrayList<>();
        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sqlGetCTHD);
            ps.setInt(1, maHD);
            try {
                ResultSet rs = ps.executeQuery();
                while (rs.next()) {
                    ds.add( new CT_HoaDon(
                            rs.getInt("STT"),
                            rs.getString("TenSanPham"),
                            rs.getString("DonViTinh"),
                            rs.getInt("SoLuong"),
                            rs.getBigDecimal("DonGia"),
                            rs.getBigDecimal("ThanhTien")
                    ));
                }
            }catch (Exception e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch (Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    public  static final String sqlKH = """
            Select * From KHACH_HANG
            Where MaKhachHang = ?
            """;

    public static KhachHang getInfoKH(int id) {
        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sqlKH);
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return new KhachHang(
                            rs.getInt("MaKhachHang"),
                            rs.getString("TenKhachHang"),
                            rs.getString("SoDienThoai"),
                            rs.getString("Email"),
                            rs.getString("DiaChi")
                    );
                }
            }catch (SQLException e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch (SQLException e ) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return null;
    }
}

package com.quickmanager.service;

import com.quickmanager.config.DBConnection;
import com.quickmanager.debug.Address;
import com.quickmanager.model.CT_HoaDon;
import com.quickmanager.model.HoaDon;
import com.quickmanager.model.KhachHang;

import java.sql.*;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class InvoiceService {
    public static final String sqlInsertHD = """
    Insert Into HOA_DON ( MaNhanVien,MaKhachHang,TongTien,GiamGia,TienKhachDua,TienThoi)
    Values(?,?,?,?,?,?);
    """;
    private static final String sqlInsertCTHD =
            "INSERT INTO CT_HOA_DON (MaHoaDon, MaSanPham, SoLuong, DonGia, ThanhTien) VALUES (?, ?, ?, ?, ?)";

    private static final String sqlUpdateSP = """
    UPDATE SAN_PHAM
    SET SoLuongTon = SoLuongTon - ?,
        TrangThai = CASE
            WHEN SoLuongTon - ? <= 0 THEN N'Ngung ban'
            ELSE TrangThai
        END
    WHERE MaSanPham = ? AND SoLuongTon >= ?;
    """;


    public static int taoHoaDonNKH(HoaDon hd, List<CT_HoaDon> ds) throws SQLException {
        try (Connection con = DBConnection.getConnection()) {
            con.setAutoCommit(false);
            try (PreparedStatement psHD = con.prepareStatement(sqlInsertHD, Statement.RETURN_GENERATED_KEYS);
                PreparedStatement psCTHD = con.prepareStatement(sqlInsertCTHD);
                PreparedStatement psUDSP =  con.prepareStatement(sqlUpdateSP)) {

                // HD
                psHD.setInt(1, hd.getMaNhanVien());
                if (hd.getMaKhachHang() == null) psHD.setNull(2, Types.INTEGER);
                else psHD.setInt(2, hd.getMaKhachHang());
                psHD.setBigDecimal(3, hd.getTongTien());
                psHD.setBigDecimal(4, hd.getGiamGia());
                psHD.setBigDecimal(5, hd.getTienKhachDua());
                psHD.setBigDecimal(6, hd.getTienThoi());

                int ktHD = psHD.executeUpdate();
                if (ktHD == 0) throw new SQLException("Tạo hóa đơn thất bại");

                // CTHD
                int maHoaDon;
                try (ResultSet key = psHD.getGeneratedKeys()) {
                    if (key.next()) maHoaDon = key.getInt(1);
                    else throw new SQLException("Lấy mã hóa đơn thất bại");
                }

                for (CT_HoaDon items : ds) {
                    psUDSP.setInt(1, items.getSoLuong());
                    psUDSP.setInt(2, items.getSoLuong());
                    psUDSP.setInt(3, items.getMaSanPham());
                    psUDSP.setInt(4, items.getSoLuong());
                    int ktUDSP = psUDSP.executeUpdate();
                    if (ktUDSP != 1) throw new SQLException("Cập nhật sản phẩm thất bại");

                    psCTHD.setInt(1, maHoaDon);
                    psCTHD.setInt(2, items.getMaSanPham());
                    psCTHD.setInt(3, items.getSoLuong());
                    psCTHD.setBigDecimal(4, items.getDonGia());
                    psCTHD.setBigDecimal(5, items.getThanhTien());
                    psCTHD.executeUpdate();
                }
                con.commit();
                return maHoaDon;
            }catch (Exception e) {
                con.rollback();
                throw e;  // gui loi ra ngoai
            }

        }
    }

    public static final String sqlGetHoaDon = """
        Select *
        From HOA_DON as hd
        Left Join KHACH_HANG as kh on kh.MaKhachHang = hd.MaKhachHang
        Where hd.NgayLap >= ? and hd.NgayLap < ?
        And (kh.TenKhachHang Like ? or kh.TenKhachHang is null)
        And CAST(hd.MaHoaDon AS VARCHAR(20)) Like ?
        """;

    public static List<HoaDon> getHoaDon(String nameKH, String maHD, LocalDate start, LocalDate end) {
        List<HoaDon> ds = new ArrayList<>();
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020, 1, 1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        String nameFilter = (nameKH == null || nameKH.isBlank()) ? "%" : "%" + nameKH.trim() + "%";
        String maHdFilter = (maHD == null || maHD.isBlank()) ? "%" : "%" + maHD.trim() + "%";
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sqlGetHoaDon)) {
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            ps.setString(3, nameFilter);
            ps.setString(4, maHdFilter);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    ds.add(new HoaDon(
                            rs.getInt("MaHoaDon"),
                            rs.getInt("MaKhachHang"),
                            rs.getString("TenKhachHang"),
                            rs.getDate("NgayLap").toLocalDate(),
                            rs.getBigDecimal("TongTien"),
                            rs.getBigDecimal("GiamGia")));
                }
            }
        } catch (Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    // Statistics helpers
    public static java.math.BigDecimal getTotalRevenue(LocalDate start, LocalDate end) {
        java.math.BigDecimal total = java.math.BigDecimal.ZERO;
        String sql = "SELECT SUM(TongTien) as Total FROM HOA_DON WHERE NgayLap >= ? AND NgayLap < ?";
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020,1,1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        try (Connection con = DBConnection.getConnection(); PreparedStatement ps = con.prepareStatement(sql)){
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            try (ResultSet rs = ps.executeQuery()){
                if (rs.next()) total = rs.getBigDecimal("Total") == null ? java.math.BigDecimal.ZERO : rs.getBigDecimal("Total");
            }
        }catch (Exception e){ System.out.println(e.getMessage()); Address.printAddress(); }
        return total;
    }

    public static int getOrderCount(LocalDate start, LocalDate end) {
        int cnt = 0;
        String sql = "SELECT COUNT(*) as Cnt FROM HOA_DON WHERE NgayLap >= ? AND NgayLap < ?";
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020,1,1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        try (Connection con = DBConnection.getConnection(); PreparedStatement ps = con.prepareStatement(sql)){
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            try (ResultSet rs = ps.executeQuery()){
                if (rs.next()) cnt = rs.getInt("Cnt");
            }
        }catch (Exception e){ System.out.println(e.getMessage()); Address.printAddress(); }
        return cnt;
    }

    public static int getProductsSold(LocalDate start, LocalDate end) {
        int cnt = 0;
        String sql = "SELECT SUM(ct.SoLuong) as TotalQty FROM CT_HOA_DON ct JOIN HOA_DON hd ON ct.MaHoaDon = hd.MaHoaDon WHERE hd.NgayLap >= ? AND hd.NgayLap < ?";
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020,1,1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        try (Connection con = DBConnection.getConnection(); PreparedStatement ps = con.prepareStatement(sql)){
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            try (ResultSet rs = ps.executeQuery()){
                if (rs.next()) cnt = rs.getInt("TotalQty");
            }
        }catch (Exception e){ System.out.println(e.getMessage()); Address.printAddress(); }
        return cnt;
    }

    public static java.util.List<com.quickmanager.model.DoanhThuNgay> getDoanhThuTheoNgay(LocalDate start, LocalDate end) {
        java.util.List<com.quickmanager.model.DoanhThuNgay> ds = new java.util.ArrayList<>();
        String sql = "SELECT CAST(NgayLap AS DATE) AS Ngay, COUNT(*) AS SoHoaDon, SUM(TongTien) AS DoanhThu FROM HOA_DON WHERE NgayLap >= ? AND NgayLap < ? GROUP BY CAST(NgayLap AS DATE) ORDER BY Ngay";
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020,1,1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        try (Connection con = DBConnection.getConnection(); PreparedStatement ps = con.prepareStatement(sql)){
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            try (ResultSet rs = ps.executeQuery()){
                while (rs.next()) {
                    java.sql.Date d = rs.getDate("Ngay");
                    ds.add(new com.quickmanager.model.DoanhThuNgay(d.toLocalDate(), rs.getInt("SoHoaDon"), rs.getBigDecimal("DoanhThu")));
                }
            }
        }catch (Exception e){ System.out.println(e.getMessage()); Address.printAddress(); }
        return ds;
    }

    public static java.util.List<com.quickmanager.model.TopSanPham> getTopSanPham(LocalDate start, LocalDate end, int limit) {
        java.util.List<com.quickmanager.model.TopSanPham> ds = new java.util.ArrayList<>();
        String sql = "SELECT sp.TenSanPham, SUM(ct.SoLuong) AS SoLuong, SUM(ct.ThanhTien) AS DoanhThu FROM CT_HOA_DON ct JOIN HOA_DON hd ON ct.MaHoaDon = hd.MaHoaDon JOIN SAN_PHAM sp ON ct.MaSanPham = sp.MaSanPham WHERE hd.NgayLap >= ? AND hd.NgayLap < ? GROUP BY sp.TenSanPham ORDER BY SUM(ct.SoLuong) DESC";
        LocalDate fromDate = (start != null) ? start : LocalDate.of(2020,1,1);
        LocalDate toDateExclusive = ((end != null) ? end : LocalDate.now()).plusDays(1);
        try (Connection con = DBConnection.getConnection(); PreparedStatement ps = con.prepareStatement(sql)){
            ps.setDate(1, Date.valueOf(fromDate));
            ps.setDate(2, Date.valueOf(toDateExclusive));
            try (ResultSet rs = ps.executeQuery()){
                int count = 0;
                while (rs.next()) {
                    ds.add(new com.quickmanager.model.TopSanPham(rs.getString("TenSanPham"), rs.getInt("SoLuong"), rs.getBigDecimal("DoanhThu")));
                    count++; if (count >= limit) break;
                }
            }
        }catch (Exception e){ System.out.println(e.getMessage()); Address.printAddress(); }
        return ds;
    }

    public static final String sqlGetCTHD = """
        SELECT 
            ROW_NUMBER() OVER (ORDER BY sp.MaSanPham) AS STT,
            hd.*,
            sp.*
        FROM CT_HOA_DON AS hd
        JOIN SAN_PHAM AS sp 
            ON hd.MaSanPham = sp.MaSanPham
        WHERE hd.MaHoaDon = ?
        """;
    public static List<CT_HoaDon> getCTHD(int maHD) {
        List<CT_HoaDon> ds = new ArrayList<>();
        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sqlGetCTHD);
            ps.setInt(1, maHD);
            try {
                ResultSet rs = ps.executeQuery();
                while (rs.next()) {
                    ds.add( new CT_HoaDon(
                            rs.getInt("STT"),
                            rs.getString("TenSanPham"),
                            rs.getString("DonViTinh"),
                            rs.getInt("SoLuong"),
                            rs.getBigDecimal("DonGia"),
                            rs.getBigDecimal("ThanhTien")
                    ));
                }
            }catch (Exception e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch (Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    public  static final String sqlKH = """
            Select * From KHACH_HANG
            Where MaKhachHang = ?
            """;

    public static KhachHang getInfoKH(int id) {
        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sqlKH);
            ps.setInt(1, id);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return new KhachHang(
                            rs.getInt("MaKhachHang"),
                            rs.getString("TenKhachHang"),
                            rs.getString("SoDienThoai"),
                            rs.getString("Email"),
                            rs.getString("DiaChi")
                    );
                }
            }catch (SQLException e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch (SQLException e ) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return null;
    }
}

package com.quickmanager.service;

import com.quickmanager.config.DBConnection;
import com.quickmanager.debug.Address;
import com.quickmanager.model.DanhMuc;
import com.quickmanager.model.SanPham;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class ProductService {
    private static final String sqlGetProducts = """
    SELECT *
    FROM SAN_PHAM sp
    JOIN DANH_MUC dm ON sp.MaDanhMuc = dm.MaDanhMuc
    WHERE sp.[TrangThai] LIKE ?
      AND (
            CAST(sp.MaSanPham AS VARCHAR(20)) LIKE ?
         OR sp.TenSanPham LIKE ?
      )
        AND dm.TenDanhMuc LIKE ?
    """;

    public static final String getDanhMuc = """
            Select * From DANH_MUC;
            """;

    public static final String sqlSearchProducts = """
        Select sp.MaSanPham,
               sp.TenSanPham,
               sp.DonViTinh,
               sp.SoLuongTon,
               sp.GiaNhap
        From SAN_PHAM sp
        Where sp.TenSanPham Like ?
            Or sp.MaSanPham like ?
        """;

    public static List<SanPham> getProduct(String key, String danhMuc, String trangThai,Boolean hh) {
        String sql = hh ? sqlGetProducts + "AND (sp.HanSuDung IS NULL OR sp.HanSuDung >= CAST(GETDATE() AS DATE))" : sqlGetProducts;
        List<SanPham> ds = new ArrayList<>();
        String string = "%" + ( key == null ? "" : key.trim()) + "%";
        String dm =  "%" + ( danhMuc == null ? "" : danhMuc.trim()) + "%";
        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sql);
            ps.setString(1, trangThai == null || trangThai.isEmpty() ? "%" : trangThai);
            ps.setString(2, string);
            ps.setString(3, string);
            ps.setString(4, dm);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    SanPham sp = new SanPham();
                    sp.setMaSanPham(rs.getInt("MaSanPham"));
                    sp.setTenSanPham(rs.getString("TenSanPham"));
                    sp.setMaDanhMuc(rs.getInt("MaDanhMuc"));
                    sp.setGiaBan(rs.getBigDecimal("GiaBan"));
                    sp.setGiaNhap(rs.getBigDecimal("GiaNhap"));
                    sp.setSoLuongTon(rs.getInt("SoLuongTon"));
                    sp.setDonViTinh(rs.getString("DonViTinh"));
                    sp.setGiaBan(rs.getBigDecimal("GiaBan"));
                    sp.setTenDanhMuc(rs.getString("TenDanhMuc"));
                    sp.setTrangThai(rs.getString("TrangThai"));
                    ds.add(sp);
                }
            }catch (Exception e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch(Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    public static List<DanhMuc> getDanhMuc() {
        List<DanhMuc> ds = new ArrayList<>();
        try (Connection conn = DBConnection.getConnection()) {
            try (PreparedStatement st = conn.prepareStatement(getDanhMuc);
                 ResultSet rs = st.executeQuery()) {
                while (rs.next()) {
                    ds.add(new DanhMuc(rs.getInt("MaDanhMuc"),rs.getString("TenDanhMuc")));
                }
            }catch (Exception e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch (Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    public static List<SanPham> searchProducts(String key) {
        List<SanPham> ds = new ArrayList<SanPham>();
        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sqlSearchProducts);
            ps.setString(1,(key == null) ? "" : "%"+key+"%");
            ps.setString(2,(key == null) ? "" : "%"+key+"%");
            try (ResultSet rs = ps.executeQuery()) {
                while(rs.next()) {
                    SanPham sp = new SanPham();
                    sp.setTenSanPham(rs.getString("TenSanPham"));
                    sp.setMaSanPham(rs.getInt("MaSanPham"));
                    sp.setDonViTinh(rs.getString("DonVitinh"));
                    sp.setGiaNhap(rs.getBigDecimal("GiaNhap"));
                    sp.setSoLuongTon(rs.getInt("SoLuongton"));
                    ds.add(sp);
                }
            }catch(Exception e) {
                System.out.println(e.getMessage());
                Address.printAddress();
            }
        }catch (Exception e) {
            System.out.println(e.getMessage());
            Address.printAddress();
        }
        return ds;
    }

    public static boolean updateProduct(SanPham sp) {
        String sqlUpdate = """
        UPDATE SAN_PHAM
        SET TenSanPham = ?,
            MaDanhMuc = ?,
            GiaNhap = ?,
            GiaBan = ?,
            SoLuongTon = ?,
            DonViTinh = ?,
            TrangThai = ?
        WHERE MaSanPham = ?
        """;

        try (Connection con = DBConnection.getConnection()) {
            PreparedStatement ps = con.prepareStatement(sqlUpdate);
            ps.setString(1, sp.getTenSanPham());
            ps.setInt(2, sp.getMaDanhMuc());
            ps.setBigDecimal(3, sp.getGiaNhap());
            ps.setBigDecimal(4, sp.getGiaBan());
            ps.setInt(5, sp.getSoLuongTon());
            ps.setString(6, sp.getDonViTinh());
            ps.setString(7, sp.getTrangThai());
            ps.setInt(8, sp.getMaSanPham());

            int rowsAffected = ps.executeUpdate();
            return rowsAffected > 0;
        } catch (Exception e) {
            System.out.println("Lỗi cập nhật sản phẩm: " + e.getMessage());
            Address.printAddress();
            return false;
        }
    }

}

